using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEngine.SceneManagement;using Newtonsoft.Json;using Newtonsoft.Json.Linq;
public static class FinishLodImport {
 static string R=>Path.GetFullPath(Path.Combine(Application.dataPath,"../../.."));static string H=>R+"/SourceAssets/B4_Finish/";const string A="Assets/Afrer_Seconds/05.Model/";
 public static object Run(){if(Application.isPlaying||SceneManager.GetActiveScene().isDirty)throw new Exception("Saved edit required");AssetDatabase.Refresh(ImportAssetOptions.ForceSynchronousImport);var plan=JArray.Parse(File.ReadAllText(H+"lod_plan.json"));var records=new List<object>();foreach(var p in plan){string cat=((string)p["asset"]).Contains("/Props/")?"Props":"Environment";foreach(int l in new[]{1,2}){string n=(string)p["name"]+"_LOD"+l,from=A+"Environment/B4/"+n+".fbx",path=A+cat+"/B4/"+n+".fbx";if(from!=path&&AssetDatabase.LoadAssetAtPath<GameObject>(from)){string err=AssetDatabase.MoveAsset(from,path);if(err!="")throw new Exception(err);}var mi=(ModelImporter)AssetImporter.GetAtPath(path);mi.importAnimation=false;mi.importCameras=false;mi.importLights=false;mi.isReadable=true;mi.importNormals=ModelImporterNormals.Import;mi.importTangents=ModelImporterTangents.CalculateMikk;var names=p["materialNames"].Select(x=>(string)x).ToArray();var mats=p["materials"].Select(x=>AssetDatabase.LoadAssetAtPath<Material>((string)x)).ToArray();for(int i=0;i<names.Length;i++)if(mats[i])mi.AddRemap(new AssetImporter.SourceAssetIdentifier(typeof(Material),"FL_SLOT_"+i.ToString("00")),mats[i]);mi.SaveAndReimport();var mf=AssetDatabase.LoadAssetAtPath<GameObject>(path).GetComponentsInChildren<MeshFilter>().Single();var m=mf.sharedMesh;var v=m.vertices;var ns=m.normals;var t=m.triangles;int bad=0,inverted=0;double total=0;for(int i=0;i<t.Length;i+=3){var cross=Vector3.Cross(v[t[i+1]]-v[t[i]],v[t[i+2]]-v[t[i]]);if(cross.sqrMagnitude<1e-16f)bad++;if(Vector3.Dot(cross,ns[t[i]]+ns[t[i+1]]+ns[t[i+2]])<-.000001f)inverted++;total+=Vector3.Dot(v[t[i]],Vector3.Cross(v[t[i+1]],v[t[i+2]]))/6.0;}Vector3 cv=new Vector3((float)p["boundsCenter"][0],(float)p["boundsCenter"][1],(float)p["boundsCenter"][2]),sz=new Vector3((float)p["boundsSize"][0],(float)p["boundsSize"][1],(float)p["boundsSize"][2]);float boundsError=Vector3.Distance(m.bounds.center,cv)+Vector3.Distance(m.bounds.size,sz);records.Add(new{name=n,path,tri=t.Length/3,degenerate=bad,inverted,boundsError,volume=total,submeshes=m.subMeshCount,originalSubmeshes=mats.Length,localPosition=mf.transform.localPosition.ToString(),localRotation=mf.transform.localEulerAngles.ToString(),localScale=mf.transform.localScale.ToString(),materialNames=mf.GetComponent<Renderer>().sharedMaterials.Select(x=>x?x.name:"NULL")});}}
 AssetDatabase.SaveAssets();File.WriteAllText(H+"lod_catalog.json",JsonConvert.SerializeObject(records,Formatting.Indented));return new{models=records.Count};}
}
